mapper.select:

		 /* getSellerMpIvDsDateDupChk */
		 	SELECT	DECODE(COUNT(*), 0, 'N', 'Y') AS DUP_YN 
	 		FROM	ICOMPORS
 			WHERE	1=1
 			AND		BUYER = #{buyer}
 			AND		PO_NO = #{po_no}
 			AND		PO_SEQ = #{po_seq}
			AND		DS_DATE = #{ch_ds_date}
			AND		STATUS <> 'D'

/*getSellerMpIvDeliveryProgressStateList_v2*/ SELECT XX.* FROM ( SELECT X.BUYER2 AS BUYER_NAME --1구매사 , DECODE(X.DS_DATE, NULL,'수주접수대상', DECODE(Y.INV_NO, NULL, '거래명세서 생성대상', DECODE(Y.DELIVERY_DATE,NULL,'납품실적 등록대상','납품완료'))) AS STATUS --2상태 , DECODE(X.DS_DATE, NULL,'/resources/imgs/State_01.png', DECODE(Y.INV_NO, NULL, '/resources/imgs/State_02.png', DECODE(Y.DELIVERY_DATE,NULL,'/resources/imgs/State_03.png','/resources/imgs/State_04.png'))) AS STATUS_BUTTON --2상태이미지 , (SELECT DECODE(COUNT(*), 0, 'N', 'Y') FROM KEP_PO_MNG WHERE BUYER = X.BUYER_CODE AND PO_NO = X.PO_NO AND PO_SEQ IN ('000000', X.PO_SEQ) AND DS_SEQ IN ('000000', X.DS_SEQ) AND STATUS = 'S' AND TYPE IN ('D','E','G','I') ) AS PMNG_STATUS , X.PO_CREATE_DATE --3발주일 , X.PO_NO --4발주번호 , X.DS_DATE --5납품예정일 , Y.INV_NO --6거래명세서번호 , Y.DELIVERY_DATE --7납품일 , X.BUYER_ITEM_NO --8품목코드 , X.DESCRIPTION --9품명 , X.SPECIFICATION --10규격 , X.ITEM_QTY --11발주수량 , X.CD_QTY --12납품예정수량 , Y.DELIVERY_QTY --13납품확정수량 , X.LEGACY_PO_NO --14구매사발주번호 , X.AGENT_PRICE --15단가 , (X.AGENT_PRICE * X.ITEM_QTY) AS AGENT_AMT , X.UNIT_MEASURE --16단위 , DECODE(SIGN(TRIM(Y.DELIVERY_DATE) - NVL(X.DS_DATE,0)),1, '납기지연납품',NULL,'미납품','납기내납품') AS DELIVERY_STATUS --17납품현황 , X.BUYER_CODE --18 , X.BYIT_COMORG_CODE --19 , X.CONTRACT_NO --20 , X.CONTRACT_SEQ --21 , X.HD_DELY_TO_LOCATION , X.DELY_TO_LOCATION --22 , X.PO_REMARK , X.PO_REMARK_2 , X.REF_PR_NO , Y.INV_QTY , X.LEGACY_PO_SEQ , Y.INVOICE_DATE , F_GET_HIDDEN_BUYER_NAME(X.BUYER_CODE, '01') AS BUYER_CODE2 , X.MAKER_NAME --제조사 추가 , X.MAKER_PART_NO --모델번호 추가 , X.PO_SEQ , X.DS_SEQ , X.AGENT , X.PR_NO , X.PR_SEQ , (SELECT COUNT(*) FROM KEP_PO_MNG WHERE BUYER = X.BUYER_CODE AND PO_NO = X.PO_NO AND PO_SEQ = X.PO_SEQ AND DS_SEQ = X.DS_SEQ AND AGENT = X.AGENT AND TYPE = 'G' AND STATUS = 'CM') AS REQ_CNT , (SELECT DECODE(COUNT(*), 0, 'Y', 'N') FROM ICOMIVDT WHERE BUYER = X.BUYER_CODE AND PO_NO = X.PO_NO AND STATUS <> 'D') AS INIT_ABLE_YN , (SELECT DECODE(COUNT(*), 0, 'N', 'Y') FROM KEP_PO_MNG WHERE BUYER = X.BUYER_CODE AND PO_NO = X.PO_NO AND AGENT = X.AGENT AND TYPE = 'I' AND STATUS = 'S') AS INFO_CHANGE_REQ_YN , X.RD_DATE , X.ST_DATE , CASE WHEN X.DS_DATE IS NOT NULL AND Y.DELIVERY_DATE IS NULL THEN CASE WHEN TO_DATE(TO_CHAR(SYSDATE,'YYYYMMDD'),'YYYYMMDD') <= TO_DATE(X.DS_DATE,'YYYYMMDD') THEN '-' ELSE '-'||(TO_DATE(TO_CHAR(SYSDATE,'YYYYMMDD'),'YYYYMMDD') - TO_DATE(X.DS_DATE,'YYYYMMDD'))||'일' END WHEN X.DS_DATE IS NOT NULL AND Y.DELIVERY_DATE IS NOT NULL THEN CASE WHEN TO_DATE(Y.DELIVERY_DATE,'YYYYMMDD') <= TO_DATE(X.DS_DATE,'YYYYMMDD') THEN '-' ELSE '-'||(TO_DATE(Y.DELIVERY_DATE,'YYYYMMDD') - TO_DATE(X.DS_DATE,'YYYYMMDD'))||'일' END ELSE '-' END AS DS_DELAY_DAY , DECODE(Y.PARCEL_YN,NULL, '-', 'N', '자차', '택배') AS PARCEL_YN_TEXT , F_GET_MIS_BUYER_MNG(X.BUYER,X.PO_NO,X.PO_SEQ) AS KEP_USER_INFO , X.DOC_TYPE , DECODE(X.DOC_TYPE,'S',X.PO_CREATE_DATE,'-') AS BFRE_STCK_YN , X.SELLER , Y.LEGACY_IV_SERIAL , DECODE(X.PROCESS_TYPE,'2',X.WAREHOUSE_CODE,Y.BUYER) AS TR_BUYER , TO_CHAR(TO_DATE(X.PORS_ADD_DATE||X.PORS_ADD_TIME,'yyyymmddhh24miss'),'yyyy-mm-dd hh24:mi') AS PORS_DATE , TO_CHAR(TO_DATE(Y.IVDT_ADD_DATE||Y.IVDT_ADD_TIME,'yyyymmddhh24miss'),'yyyy-mm-dd hh24:mi') AS IVDT_DATE , TO_CHAR(Y.DELIVERY_ADD_DATE,'yyyy-mm-dd hh24:mi') AS DELIVERY_ADD_DATE , X.PROCESS_TYPE , X.SELLER_ITEM_NO , DECODE(X.PROCESS_TYPE, '0', '직납', '2', 'TR(' || (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT4 = 'B' AND FLAG = 'Y' AND TEXT1 = X.TR_CENTER) || ')', ' ') AS PROCESS_TYPE_TEXT FROM ( SELECT ( SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = F_GET_HIDDEN_BUYER_NAME(B.BUYER, '01')) AS BUYER2 , A.PO_CREATE_DATE AS PO_CREATE_DATE , B.PO_NO AS PO_NO , B.PO_SEQ AS PO_SEQ , C.DS_DATE AS DS_DATE , B.BUYER_ITEM_NO AS BUYER_ITEM_NO , B.DESCRIPTION AS DESCRIPTION , B.SPECIFICATION AS SPECIFICATION , B.ITEM_QTY AS ITEM_QTY , C.CD_QTY AS CD_QTY , B.LEGACY_PO_NO AS LEGACY_PO_NO , B.LEGACY_PO_SEQ AS LEGACY_PO_SEQ , B.AGENT_PRICE AS AGENT_PRICE , B.UNIT_MEASURE AS UNIT_MEASURE , B.BUYER BUYER_CODE , B.BYIT_COMORG_CODE AS BYIT_COMORG_CODE , B.CONTRACT_NO AS CONTRACT_NO , B.CONTRACT_SEQ AS CONTRACT_SEQ , B.BUYER BUYER , A.DELY_TO_LOCATION AS HD_DELY_TO_LOCATION , B.PO_REMARK AS PO_REMARK , A.PO_REMARK AS PO_REMARK_2 , B.REF_PR_NO , D.MAKER_NAME --제조사 추가 , D.MAKER_PART_NO --모델번호 추가 , C.DS_SEQ , A.AGENT , D.PR_NO , D.PR_SEQ , B.RD_DATE , B.ST_DATE , A.DOC_TYPE , B.SELLER , B.PROCESS_TYPE , B.WAREHOUSE_CODE , C.ADD_DATE AS PORS_ADD_DATE , C.ADD_TIME AS PORS_ADD_TIME , B.SELLER_ITEM_NO ,DECODE((SELECT COUNT(*) FROM ICOMCOD2 WHERE COMPANY_CODE = DECODE(B.PROCESS_TYPE,'2',F_GET_HUB_INFO(A.BUYER,A.PO_NO,'2'),A.BUYER) AND TYPE = 'C012' AND CODE = DECODE(B.PROCESS_TYPE,'2','001',A.DELY_TO_LOCATION)),0,A.DELY_TO_LOCATION, (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = DECODE(B.PROCESS_TYPE,'2',F_GET_HUB_INFO(A.BUYER,A.PO_NO,'2'),A.BUYER) AND TYPE = 'C012' AND CODE = DECODE(B.PROCESS_TYPE,'2','001',A.DELY_TO_LOCATION))) AS DELY_TO_LOCATION , NVL((SELECT DELY_TO_CENTER FROM SUPLINFO2 WHERE SUPPLIER = A.AGENT), B.WAREHOUSE_CODE) AS TR_CENTER FROM ICOMPOHD A, ICOMPODT B, ICOMPORS C, ICOMPRDT D WHERE A.BUYER = B.BUYER
AND A.AGENT = #{st_com_code} AND A.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.AGENT = #{st_com_code} AND B.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND C.AGENT = #{st_com_code} AND C.DS_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.AGENT = #{st_com_code}
AND A.AGENT = #{st_com_code}
AND A.BUYER = #{st_buyer_code}
AND B.BUYER_ITEM_NO LIKE UPPER('%'||TRIM(#{st_buyer_item_no})||'%')
AND B.DESCRIPTION LIKE '%'||TRIM(#{st_description})||'%'
AND A.DOC_TYPE = #{st_bfre_stck_yn}
AND A.DOC_TYPE != 'S'
AND A.PO_NO = B.PO_NO AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND B.BUYER = C.BUYER(+) AND B.PO_NO = C.PO_NO(+) AND B.PO_SEQ = C.PO_SEQ(+) AND C.STATUS(+) <> 'D' AND B.BUYER=D.BUYER --추가 AND B.PR_NO= D.PR_NO --추가 AND B.PR_SEQ=D.PR_SEQ --추가 ) X, (SELECT E.PO_NO ,E.PO_SEQ ,E.BUYER ,E.DS_DATE ,E.INV_NO ,E.INV_QTY ,E.DELIVERY_DATE ,E.INVOICE_DATE ,F.PARCEL_YN ,E.STATUS ,E.DELIVERY_QTY ,F.LEGACY_IV_SERIAL ,E.DELIVERY_ADD_DATE, E.ADD_DATE AS IVDT_ADD_DATE, E.ADD_TIME AS IVDT_ADD_TIME FROM ICOMIVDT E, ICOMIVHD F WHERE E.BUYER = F.BUYER AND E.INV_NO = F.INV_NO AND E.STATUS != 'D' AND F.STATUS != 'D' AND F.AGENT = #{st_com_code}
AND E.ADD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND E.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date}
)Y WHERE X.BUYER = Y.BUYER(+) AND X.PO_NO = Y.PO_NO(+) AND X.PO_SEQ = Y.PO_SEQ(+) AND X.DS_DATE = Y.DS_DATE(+) AND Y.STATUS(+) <> 'D'
AND Y.STATUS != 'D' AND Y.IVDT_ADD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND Y.STATUS != 'D' AND Y.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND DECODE(X.DS_DATE, NULL,'수주접수대상', DECODE(Y.INV_NO, NULL, '거래명세서 생성대상', DECODE(Y.DELIVERY_DATE,NULL,'납품실적 등록대상','납품완료'))) = #{st_status}
AND DECODE(Y.PARCEL_YN,NULL, '-', 'N', '자차', '택배') = #{st_parcel_yn_text}
AND CASE WHEN DECODE(Y.DELIVERY_DATE,NULL,TO_DATE(TO_CHAR(SYSDATE,'YYYYMMDD'),'YYYYMMDD'),TO_DATE(Y.DELIVERY_DATE,'YYYYMMDD')) > TO_DATE(X.DS_DATE,'YYYYMMDD') THEN 'Y' ELSE 'N' END = #{st_delay_yn}
ORDER BY PO_CREATE_DATE DESC , BUYER_NAME, PO_NO )XX WHERE 1=1
AND XX.PO_NO IN
UPPER(#{item})
AND XX.LEGACY_PO_NO IN
UPPER(#{item})
AND REPLACE(UPPER(XX.BUYER_NAME),' ','') LIKE '%'||UPPER(TRIM(REPLACE(#{st_buyer_name},' ','')))||'%'
